import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import Button from "../components/Button";
import Icon from "../components/Icon"; // Note: Icon component is imported but not used in the provided code

const CreateLOTO = () => {
  const [formData, setFormData] = useState({
    shift: "A",
    location: "PKG", // Default location
    line: "", // Selected line
    machine: "", // Selected machine
    isolatedPart: "", // Final isolated part description
    reason: "",
    ptwNumber: "N/A",
    expectedDuration: "",
    supervisor: "", // ID of the assigned supervisor
    energyTypes: [{ type: "", isolationPoint: "" }],
  });
  const [loading, setLoading] = useState(false); // Note: 'loading' state is defined but not used for initial data fetch
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");
  const [supervisors, setSupervisors] = useState([]);
  const [fetchingSupervisors, setFetchingSupervisors] = useState(true);
  const [showCustomReason, setShowCustomReason] = useState(false);
  const [customReason, setCustomReason] = useState("");
  const [showCustomLocation, setShowCustomLocation] = useState(false);
  const [customLocation, setCustomLocation] = useState("");
  const [showCustomMachine, setShowCustomMachine] = useState(false);
  const [customMachine, setCustomMachine] = useState("");
  const navigate = useNavigate();

