                        >
                          <div className="d-flex justify-content-between align-items-center mb-2">
                            <h6 className="mb-0">Energy Type {index + 1}</h6>
                            <button
                              type="button"
                              className="btn btn-sm btn-danger"
                              onClick={() => removeEnergyType(index)}
                              disabled={energyTypes.length <= 1}
                            >
                              <span className="me-1">🗑️</span> Remove
                            </button>
                          </div>
                          <div className="row">
                            <div className="col-md-6">
                              <label className="form-label fw-medium">
                                Energy Type
                              </label>
                              <select
                                value={energy.type}
                                onChange={(e) =>
                                  handleEnergyTypeChange(
                                    index,
                                    "type",
                                    e.target.value
                                  )
                                }
                                className="form-control"
                                style={{
                                  borderRadius: "0.75rem",
                                  border: "2px solid #e2e8f0",
                                  background: "rgba(255, 255, 255, 0.9)",
                                  backdropFilter: "blur(10px)",
                                }}
                                required
                              >
                                <option value="">Select energy type</option>
                                {energyTypeOptions.map((et) => (
                                  <option key={et.name} value={et.name}>
                                    {et.symbol} {et.name}
                                  </option>
                                ))}
                              </select>
                            </div>
                            <div className="col-md-6">
                              <label className="form-label fw-medium">
                                Isolation Point Reference
                              </label>
                              <input
                                type="text"
                                value={energy.isolationPoint}
                                onChange={(e) =>
                                  handleEnergyTypeChange(
                                    index,
                                    "isolationPoint",
                                    e.target.value
                                  )
                                }
                                placeholder="Enter isolation point reference"
                                className="form-control"
                                style={{
                                  borderRadius: "0.75rem",
                                  border: "2px solid #e2e8f0",
                                  background: "rgba(255, 255, 255, 0.9)",
                                  backdropFilter: "blur(10px)",
                                }}
                                required
                              />
                            </div>
                          </div>
                        </div>
                      ))}
                      <button
                        type="button"
                        className="btn btn-outline-primary hover-scale"
                        onClick={addEnergyType}
                      >
                        <span className="me-2">➕</span> Add Another Energy Type
                      </button>
                    </div>
                  </div>

                  {/* --- START OF TARGET SECTION: Assign Supervisor for Verification (Optional) --- */}
                  <div className="col-12 mb-4">
                    <div className="form-group">
                      <label className="form-label fw-medium">
                        Assign Supervisor for Verification (Optional)
                      </label>
                      {fetchingSupervisors ? (
                        <div className="d-flex align-items-center">
                          <span
                            className="spinner-border spinner-border-sm me-2"
                            role="status"
                            aria-hidden="true"
                          ></span>
                          <span>Loading supervisors...</span>
                        </div>
                      ) : (
                        <select
                          name="supervisor"
                          value={supervisor}
                          onChange={onChange}
                          className="form-control"
                          style={{
                            borderRadius: "0.75rem",
                            border: "2px solid #e2e8f0",
                            background: "rgba(255, 255, 255, 0.9)",
                            backdropFilter: "blur(10px)",
                          }}
                        >
                          <option value="">
                            None - Any supervisor can verify
                          </option>
                          {safeSupervisors // Use safeSupervisors variable here
                            .filter((sup) => sup.role === "supervisor") // Filter by role
                            .map((sup) => (
                              <option key={sup._id} value={sup._id}>
                                {sup.firstName} {sup.lastName}
                              </option>
                            ))}
                        </select>
                      )}
                      <div className="form-text mt-2">
                        Select a specific supervisor who will verify this LOTO
                        request. If none selected, any supervisor can verify.
                      </div>
                    </div>
                  </div>
                  {/* --- END OF TARGET SECTION --- */}

                  {/* Action Buttons */}
                  <div className="col-12">
                    <div className="d-flex gap-2">
                      <Button
                        type="submit"
                        variant="primary"
                        disabled={submitting}
                        className="hover-scale"
                      >
                        {submitting ? (
                          <>
                            <span
                              className="spinner-border spinner-border-sm me-2"
                              role="status"
                              aria-hidden="true"
                            ></span>
                            Creating...
                          </>
                        ) : (
                          <>
                            <span className="me-2">💾</span> Create LOTO
                          </>
                        )}
                      </Button>
                      <Button
                        variant="secondary"
                        onClick={() => navigate("/loto-list")}
                        className="hover-scale"
                      >
                        <span className="me-2">❌</span> Cancel
                      </Button>
                      <Button
                        variant="outline-primary"
                        onClick={() => navigate("/Home")}
                        className="hover-scale"
                      >
                        <span className="me-2">🏠</span> Home
                      </Button>
                    </div>
                  </div>
                </div>
              </form>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CreateLOTO;
